PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL,profiles TEXT NOT NULL DEFAULT '[]',telegram_id TEXT UNIQUE,disabled INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE profiles(id TEXT PRIMARY KEY,name TEXT NOT NULL,settings TEXT NOT NULL DEFAULT '{}',enabled INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE applications(id TEXT PRIMARY KEY,name TEXT NOT NULL,profiles TEXT NOT NULL,scopes TEXT NOT NULL,bots TEXT NOT NULL,rate INTEGER NOT NULL DEFAULT 60,run_limit INTEGER NOT NULL DEFAULT 3,disabled INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE api_keys(id TEXT PRIMARY KEY,app_id TEXT NOT NULL REFERENCES applications(id),hash TEXT UNIQUE NOT NULL,prefix TEXT NOT NULL,expires INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE secrets(id TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE connections(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL REFERENCES profiles(id),name TEXT NOT NULL,kind TEXT NOT NULL,mode TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'paused',config TEXT NOT NULL DEFAULT '{}',last_seen INTEGER,created INTEGER NOT NULL);
CREATE TABLE bots(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL REFERENCES profiles(id),connection_id TEXT NOT NULL REFERENCES connections(id),remote_profile TEXT NOT NULL,name TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,UNIQUE(connection_id,remote_profile));
CREATE TABLE conversations(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL REFERENCES profiles(id),connection_id TEXT REFERENCES connections(id),external_namespace TEXT NOT NULL,external_id TEXT NOT NULL,phone TEXT,state TEXT NOT NULL DEFAULT 'ai',owner TEXT,epoch INTEGER NOT NULL DEFAULT 0,session TEXT NOT NULL,topic TEXT,tags TEXT NOT NULL DEFAULT '[]',last_customer INTEGER NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL,UNIQUE(profile_id,external_namespace,external_id));
CREATE TABLE messages(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL,conversation_id TEXT NOT NULL REFERENCES conversations(id),direction TEXT NOT NULL,author TEXT NOT NULL,text TEXT NOT NULL,attachments TEXT NOT NULL DEFAULT '[]',external_id TEXT,created INTEGER NOT NULL);
CREATE TABLE inbox(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL,event_key TEXT UNIQUE NOT NULL,conversation_id TEXT,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created INTEGER NOT NULL);
CREATE TABLE outbox(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL,conversation_id TEXT,connection_id TEXT,epoch INTEGER,kind TEXT NOT NULL,actor TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',external_id TEXT,error TEXT,dedupe TEXT UNIQUE NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE events(id INTEGER PRIMARY KEY AUTOINCREMENT,profile_id TEXT NOT NULL,kind TEXT NOT NULL,resource_id TEXT,payload TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT,profile_id TEXT,actor TEXT NOT NULL,operation TEXT NOT NULL,resource_id TEXT,request_id TEXT,created INTEGER NOT NULL);
CREATE TABLE receipts(scope TEXT NOT NULL,key TEXT NOT NULL,fingerprint TEXT NOT NULL,response TEXT,status INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,PRIMARY KEY(scope,key));
CREATE TABLE presence(profile_id TEXT NOT NULL,actor TEXT NOT NULL,present INTEGER NOT NULL,updated INTEGER NOT NULL,PRIMARY KEY(profile_id,actor));
CREATE TABLE tickets(id TEXT PRIMARY KEY,number TEXT UNIQUE NOT NULL,profile_id TEXT NOT NULL,conversation_id TEXT NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',owner TEXT,response_due_at INTEGER,first_response_at INTEGER,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE ticket_updates(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL,actor TEXT NOT NULL,text TEXT NOT NULL,internal INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE consents(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL,conversation_id TEXT NOT NULL,status TEXT NOT NULL,evidence TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE surveys(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL,conversation_id TEXT NOT NULL,app_id TEXT,score INTEGER,comment TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',created INTEGER NOT NULL);
CREATE TABLE documents(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL,title TEXT NOT NULL,kind TEXT NOT NULL,url TEXT,media_id TEXT,status TEXT NOT NULL DEFAULT 'pending',error TEXT,created INTEGER NOT NULL);
CREATE VIRTUAL TABLE chunks USING fts5(profile_id UNINDEXED,document_id UNINDEXED,text,url UNINDEXED);
CREATE TABLE media(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL,size INTEGER NOT NULL,object_key TEXT NOT NULL,actor TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE bot_runs(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL,bot_id TEXT NOT NULL,actor TEXT NOT NULL,conversation_id TEXT,epoch INTEGER,status TEXT NOT NULL DEFAULT 'queued',input TEXT NOT NULL,result TEXT,remote_id TEXT,error TEXT,phase TEXT NOT NULL DEFAULT 'external',context TEXT NOT NULL DEFAULT '{}',created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE webhook_subscriptions(id TEXT PRIMARY KEY,app_id TEXT NOT NULL,profile_id TEXT NOT NULL,url TEXT NOT NULL,events TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,created INTEGER NOT NULL);
CREATE TABLE webhook_deliveries(id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL,event_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_at INTEGER NOT NULL,last_error TEXT,created INTEGER NOT NULL,UNIQUE(subscription_id,event_id));
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE INDEX inbox_pending ON inbox(profile_id,status,created);
CREATE INDEX outbox_pending ON outbox(profile_id,status,created);
CREATE INDEX runs_pending ON bot_runs(profile_id,status,created);
CREATE INDEX messages_history ON messages(conversation_id,created,id);
CREATE INDEX conversations_recent ON conversations(profile_id,updated,id);
CREATE INDEX events_profile ON events(profile_id,id);
CREATE INDEX webhook_pending ON webhook_deliveries(status,next_at);
